/**
 * Profile-aware model selection generated by Rabetbase CLI.
 * Do not add application-specific Dataset codes to this file.
 */

import type { ModelsConfig } from "@lovrabet/sdk";

interface ModelProfile {
  appCode: string;
  runtimeDomain: string;
}

interface ModelEntryMetadata {
  alias: string;
  tableName: string;
  name: string;
}

type ModelEntry = ModelEntryMetadata &
  (
    | { datasetCode: string; datasetCodes?: never }
    | { datasetCode?: never; datasetCodes: Record<string, string> }
  );

interface ModelRegistry {
  defaultProfile: string;
  profiles: Record<string, ModelProfile>;
  models: readonly ModelEntry[];
}

function normalizeDomain(value: string | undefined): string | undefined {
  return value?.trim().replace(/\/+$/, "");
}

function injectedRuntimeDomain(): string | undefined {
  if (typeof window === "undefined") return undefined;
  const globalWindow = window as Window & {
    __GLOBAL__?: {
      deploymentConfig?: { RUNTIME_API_DOMAIN?: string };
    };
  };
  return normalizeDomain(
    globalWindow.__GLOBAL__?.deploymentConfig?.RUNTIME_API_DOMAIN,
  );
}

function selectProfile(
  registry: ModelRegistry,
  projectRuntimeDomain: string,
): readonly [string, ModelProfile] {
  const runtimeDomain =
    injectedRuntimeDomain() ?? normalizeDomain(projectRuntimeDomain);
  const matches = Object.entries(registry.profiles).filter(
    ([, profile]) => normalizeDomain(profile.runtimeDomain) === runtimeDomain,
  );

  if (matches.length > 1) {
    throw new Error(
      `Multiple Lovrabet model profiles match Runtime Domain "${runtimeDomain}". ` +
        "Give each profile a distinct Runtime Domain.",
    );
  }
  if (matches.length === 1) return matches[0]!;

  throw new Error(
    `No Lovrabet model profile matches Runtime Domain "${runtimeDomain ?? "(not set)"}". ` +
      "Run `rabetbase api pull` after verifying the current project routing.",
  );
}

export function resolveActiveModelConfig(
  registry: ModelRegistry,
  projectRuntimeDomain: string,
): {
  profileName: string;
  appCode: string;
  runtimeDomain: string;
  modelsConfig: ModelsConfig;
} {
  const [profileName, profile] = selectProfile(registry, projectRuntimeDomain);
  const models = registry.models.flatMap((model) => {
    const datasetCode = model.datasetCode ?? model.datasetCodes?.[profileName];
    return datasetCode
      ? [
          {
            datasetCode,
            tableName: model.tableName,
            name: model.name,
            alias: model.alias,
          },
        ]
      : [];
  });

  return {
    profileName,
    appCode: profile.appCode,
    runtimeDomain: profile.runtimeDomain,
    modelsConfig: { appCode: profile.appCode, models },
  };
}
